const SHEET_URL = "https://script.google.com/macros/s/AKfycbz-eTiajmYUXkYGmd181OTxL49SiFdKXR1Mqf93oQ1Xljc1TaX9m8LBzrSgQlsSYkserQ/exec"; // ← Apps Script 웹앱 URL 붙여넣기

// 사진을 포함하여 구글 시트+드라이브에 제출
async function submitToSheet(data, photos) {
  if (!SHEET_URL) return { skipped: true };

  // 사진을 base64로 변환하여 포함
  const photoDataList = await Promise.all(
    photos.map(async (p) => {
      // 이미 base64 data URL인 경우 그대로 사용
      return { data: p.url, type: "image/jpeg", name: p.name };
    })
  );

  const payload = { ...data, photos: photoDataList };

  try {
    // no-cors로 전송 (Apps Script는 CORS 헤더가 없어 response를 읽을 수 없지만 전송은 됨)
    await fetch(SHEET_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      mode: "no-cors",
    });
    return { ok: true };
  } catch (err) {
    console.error("Sheet submit error:", err);
    throw err;
  }
}

