function Detail({ cat, item, onBack, onDone }) {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [loc, setLoc] = useState("");
  const [desc, setDesc] = useState("");
  const [photos, setPhotos] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [uploadStep, setUploadStep] = useState(null);
  // uploadStep: null | { step: 'photos'|'sheet'|'done'|'error', photosDone: number, photosTotal: number, links: [] }
  const [success, setSuccess] = useState(false);
  const [resultInfo, setResultInfo] = useState(null);

  const isConnected = !!SHEET_URL;
  const canSubmit = name && phone && desc;

  const handlePhotos = e => {
    Array.from(e.target.files).forEach(f => {
      const r = new FileReader();
      r.onload = ev => setPhotos(p => p.length < 5 ? [...p,{url:ev.target.result,name:f.name}] : p);
      r.readAsDataURL(f);
    });
  };

  const handleSubmit = async () => {
    if (!canSubmit || submitting) return;
    setSubmitting(true);

    const entry = {
      ts: new Date().toLocaleString('ko-KR'),
      cat: cat.label, item: item.text,
      name, phone, loc, desc,
    };

    try {
      // 로컬 저장
      const counts = await getCounts();
      counts[item.id] = (counts[item.id]||0)+1;
      await saveCounts(counts);
      await addSub({ ...entry, photoCount: photos.length });

      if (isConnected && photos.length > 0) {
        // 사진 업로드 진행 표시
        setUploadStep({ step: 'photos', photosDone: 0, photosTotal: photos.length, links: [] });

        const photoDataList = photos.map((p, i) => ({
          data: p.url,
          type: 'image/jpeg',
          name: `${name}_${item.id}_${i+1}_${Date.now()}.jpg`
        }));

        // 사진 개수 업데이트 시뮬레이션 (실제 업로드는 Apps Script에서 처리)
        for (let i = 0; i < photos.length; i++) {
          await new Promise(r => setTimeout(r, 300));
          setUploadStep(prev => ({ ...prev, photosDone: i+1 }));
        }

        setUploadStep(prev => ({ ...prev, step: 'sheet' }));
        await new Promise(r => setTimeout(r, 200));

        // 구글 시트+드라이브에 전송
        const payload = { ...entry, photos: photoDataList };
        await fetch(SHEET_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          mode: 'no-cors',
        });

        setUploadStep(prev => ({ ...prev, step: 'done' }));
        setResultInfo({ photoCount: photos.length, sheetSaved: true });

      } else if (isConnected) {
        setUploadStep({ step: 'sheet', photosDone: 0, photosTotal: 0, links: [] });
        const payload = { ...entry, photos: [] };
        await fetch(SHEET_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          mode: 'no-cors',
        });
        setUploadStep(prev => ({ ...prev, step: 'done' }));
        setResultInfo({ photoCount: 0, sheetSaved: true });
      } else {
        setResultInfo({ photoCount: photos.length, sheetSaved: false });
      }

      await new Promise(r => setTimeout(r, 400));
      setSuccess(true);

    } catch(err) {
      console.error(err);
      setUploadStep(prev => prev ? { ...prev, step: 'error' } : null);
      alert("제출 오류가 발생했습니다. 다시 시도해 주세요.");
    } finally {
      setSubmitting(false);
    }
  };

  const stepLabel = (step) => {
    if (!uploadStep) return null;
    switch(step) {
      case 'photos': return uploadStep.step === 'photos' ? 'loading' : uploadStep.step === 'sheet' || uploadStep.step === 'done' ? 'done' : 'pending';
      case 'sheet': return uploadStep.step === 'sheet' ? 'loading' : uploadStep.step === 'done' ? 'done' : 'pending';
      default: return 'pending';
    }
  };

  const progress = uploadStep
    ? uploadStep.step === 'done' ? 100
    : uploadStep.step === 'sheet' ? 80
    : uploadStep.photosTotal > 0 ? Math.round((uploadStep.photosDone / uploadStep.photosTotal) * 75)
    : 10
    : 0;

  return (
    <div className="detail-page">
      <div className="topbar">
        <div className="topbar-in">
          <button className="tb-back" onClick={onBack}>← 목록</button>
          <span className="tb-title">부적합 내용 제출</span>
          <div style={{width:60}} />
        </div>
      </div>
      <div className="det-body">
        <div className="det-in">
          <div className="item-card">
            <span className="ic-icon">{cat.icon}</span>
            <div>
              <div className="ic-kec">{item.kec}</div>
              <div className="ic-ttl">{item.text}</div>
              <div className="ic-cat">{cat.label} 분류</div>
            </div>
          </div>
          <div className="item-desc">{item.desc}</div>

          {/* 구글 시트 연결 상태 */}
          <div className={`sheet-banner ${isConnected ? 'connected' : 'disconnected'}`}>
            <div className={`sb-dot ${isConnected ? 'on' : 'off'}`} />
            <div className={`sb-text ${isConnected ? 'connected' : 'disconnected'}`}>
              {isConnected ? (
                <>
                  <strong>📊 구글 시트 + Drive 연동됨</strong>
                  <span>제출 시 시트에 자동 기록되고, 사진은 Google Drive에 업로드됩니다.</span>
                </>
              ) : (
                <>
                  <strong>⚠️ 구글 시트 미연동</strong>
                  <span>코드 상단 SHEET_URL을 입력하면 시트 자동 기록 및 Drive 사진 업로드가 활성화됩니다.</span>
                </>
              )}
            </div>
          </div>

          {/* 업로드 진행 상태 */}
          {uploadStep && (
            <div className="upload-progress">
              <div className="up-title">📤 제출 진행 중...</div>
              <div className="up-item">
                <div className={`up-dot ${stepLabel('photos')}`} />
                <span>
                  사진 업로드
                  {uploadStep.photosTotal > 0 && ` (${uploadStep.photosDone}/${uploadStep.photosTotal}장)`}
                  {stepLabel('photos') === 'done' && ' ✓'}
                </span>
              </div>
              <div className="up-item">
                <div className={`up-dot ${stepLabel('sheet')}`} />
                <span>
                  구글 시트 기록
                  {stepLabel('sheet') === 'done' && ' ✓'}
                </span>
              </div>
              <div className="up-bar-wrap">
                <div className="up-bar" style={{width: `${progress}%`}} />
              </div>
            </div>
          )}

          <div className="form-sec">
            <div className="fs-ttl">제출자 정보</div>
            <div className="f-grid">
              <div className="f-row">
                <label className="f-label">이름 <span className="req">*</span></label>
                <input className="f-input" placeholder="성명" value={name} onChange={e=>setName(e.target.value)} />
              </div>
              <div className="f-row">
                <label className="f-label">휴대폰번호 <span className="req">*</span></label>
                <input className="f-input" type="tel" placeholder="기프티콘 전송에 활용" value={phone} onChange={e=>setPhone(e.target.value)} />
              </div>
            </div>
          </div>

          <div className="form-sec">
            <div className="fs-ttl">현장 정보</div>
            <div className="f-row">
              <label className="f-label">점검 현장 위치</label>
              <input className="f-input" placeholder="예) 서울 강남구 OO빌딩 지하2층 전기실" value={loc} onChange={e=>setLoc(e.target.value)} />
            </div>
            <div className="f-row">
              <label className="f-label">부적합 내용 설명 <span className="req">*</span></label>
              <textarea className="f-area" placeholder={"발견된 부적합 사항의 상세 내용을 입력해 주세요.\n(발생 원인, 위험 요소, 조치 방향 등)"} value={desc} onChange={e=>setDesc(e.target.value)} rows={5} />
            </div>
          </div>

          <div className="form-sec">
            <div className="fs-ttl">현장 사진 (최대 5장)</div>
            <div className="photo-zone">
              <input type="file" accept="image/*" multiple onChange={handlePhotos} />
              <div className="pz-icon">📷</div>
              <p>탭하여 사진 업로드</p>
              <small>JPG, PNG · 장당 최대 10MB · {isConnected ? 'Google Drive에 자동 저장됩니다' : '개인정보 노출 주의'}</small>
            </div>
            {photos.length > 0 && (
              <div className="photo-grid">
                {photos.map((p,i) => (
                  <div className="photo-th" key={i}>
                    <img src={p.url} alt="" />
                    <button className="photo-del" onClick={()=>setPhotos(pp=>pp.filter((_,j)=>j!==i))}>×</button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="submit-area">
            <button className="sub-btn" onClick={handleSubmit} disabled={!canSubmit||submitting}>
              {submitting ? "제출 중..." : "부적합 내용 제출하기"}
            </button>
            <p className="sub-note">
              {isConnected
                ? "사진은 Google Drive에, 정보는 Google Sheets에 자동 저장됩니다."
                : "제출된 정보는 전기안전그루터기 어플 제작에 활용됩니다."}
            </p>
          </div>
        </div>
      </div>

      {success && (
        <div className="suc-bg">
          <div className="suc-card">
            <span className="si">✅</span>
            <h2>제출 완료!</h2>
            <p>소중한 현장 의견 감사합니다.<br/>수집된 정보는 전기안전그루터기<br/>어플 제작에 활용됩니다.</p>
            {resultInfo && (
              <div className="suc-info">
                <div className="suc-info-row">
                  <span className="label">시트 기록</span>
                  <span>{resultInfo.sheetSaved ? '✅ Google Sheets 저장 완료' : '💾 앱 내부 저장'}</span>
                </div>
                <div className="suc-info-row">
                  <span className="label">사진</span>
                  <span>{resultInfo.photoCount > 0 ? (resultInfo.sheetSaved ? `📁 Drive 업로드 ${resultInfo.photoCount}장` : `${resultInfo.photoCount}장 첨부`) : '사진 없음'}</span>
                </div>
                <div className="suc-info-row">
                  <span className="label">제출자</span>
                  <span>{name} · {phone}</span>
                </div>
              </div>
            )}
            <button className="suc-btn" onClick={onDone}>목록으로 돌아가기</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [page, setPage] = useState("landing");
  const [showConsent, setShowConsent] = useState(false);
  const [selCat, setSelCat] = useState(null);
  const [selItem, setSelItem] = useState(null);
  return (
    <>
      <style>{css}</style>
      {page === "landing" && (
        <>
          <Landing onStart={() => setShowConsent(true)} />
          {showConsent && (
            <Consent
              onAgree={() => { setShowConsent(false); setPage("participation"); }}
              onClose={() => setShowConsent(false)}
            />
          )}
        </>
      )}
      {page === "participation" && (
        <Participation
          onSelect={(cat,item) => { setSelCat(cat); setSelItem(item); setPage("detail"); }}
          onBack={() => setPage("landing")}
        />
      )}
      {page === "detail" && selItem && (
        <Detail
          cat={selCat} item={selItem}
          onBack={() => setPage("participation")}
          onDone={() => setPage("participation")}
        />
      )}
    </>
  );
}
